<?php
require_once dirname(__DIR__).'/includes/functions.php';require_admin();
$stats=['students'=>$con->query("SELECT COUNT(*) n FROM users WHERE role='student' AND deleted_at IS NULL")->fetch_assoc()['n'],'careers'=>$con->query("SELECT COUNT(*) n FROM careers WHERE is_active=1")->fetch_assoc()['n'],'today'=>$con->query("SELECT COUNT(*) n FROM user_simulation_progress WHERE status='completed' AND DATE(completed_at)=CURDATE()")->fetch_assoc()['n'],'pass'=>$con->query("SELECT COALESCE(AVG(passed)*100,0) n FROM quiz_attempts WHERE completed_at IS NOT NULL")->fetch_assoc()['n']];
$days=$con->query("SELECT DATE(created_at) d,COUNT(*) n FROM users WHERE created_at>=DATE_SUB(CURDATE(),INTERVAL 29 DAY) GROUP BY DATE(created_at)")->fetch_all(MYSQLI_ASSOC);$completions=$con->query("SELECT DATE(completed_at) d,COUNT(*) n FROM user_simulation_progress WHERE completed_at>=DATE_SUB(CURDATE(),INTERVAL 29 DAY) GROUP BY DATE(completed_at)")->fetch_all(MYSQLI_ASSOC);$explored=$con->query("SELECT c.title,COUNT(p.id) n FROM careers c JOIN career_simulations s ON s.career_id=c.id JOIN user_simulation_progress p ON p.simulation_id=s.id GROUP BY c.id ORDER BY n DESC LIMIT 8")->fetch_all(MYSQLI_ASSOC);$pf=$con->query("SELECT passed,COUNT(*) n FROM quiz_attempts WHERE completed_at IS NOT NULL GROUP BY passed")->fetch_all(MYSQLI_ASSOC);$riasec=$con->query("SELECT interest_type,AVG(score) n FROM user_interest_scores GROUP BY interest_type")->fetch_all(MYSQLI_ASSOC);
$pageTitle='Admin dashboard';require __DIR__.'/includes/header.php';?>
<div class="row g-3 mb-4"><?php foreach([['Students',$stats['students'],'people'],['Active careers',$stats['careers'],'briefcase'],['Completed today',$stats['today'],'check2-circle'],['Quiz pass rate',round($stats['pass']).'%','graph-up']] as $s):?><div class="col-sm-6 col-xl-3"><div class="card metric p-4"><i class="bi bi-<?=$s[2]?> fs-3 text-primary"></i><div class="text-muted"><?=$s[0]?></div><div class="h2 mb-0"><?=$s[1]?></div></div></div><?php endforeach?></div><div class="row g-4"><div class="col-xl-8"><div class="card p-4"><h2 class="h5">Registrations & completions · 30 days</h2><div class="chart-box"><canvas id="trend"></canvas></div></div></div><div class="col-xl-4"><div class="card p-4"><h2 class="h5">Quiz outcomes</h2><div class="chart-box"><canvas id="passChart"></canvas></div></div></div><div class="col-xl-6"><div class="card p-4"><h2 class="h5">Most explored careers</h2><div class="chart-box"><canvas id="careersChart"></canvas></div></div></div><div class="col-xl-6"><div class="card p-4"><h2 class="h5">Aggregate RIASEC</h2><div class="chart-box"><canvas id="riaChart"></canvas></div></div></div></div>
<script>const days=[...Array(30)].map((_,i)=>{let d=new Date();d.setDate(d.getDate()-29+i);return d.toISOString().slice(0,10)}),map=(rows)=>Object.fromEntries(rows.map(x=>[x.d,+x.n]));document.addEventListener('DOMContentLoaded',()=>{new Chart(trend,{type:'line',data:{labels:days,datasets:[{label:'Registrations',data:days.map(d=>map(<?=json_encode($days)?>)[d]||0),borderColor:'#173b67'},{label:'Completions',data:days.map(d=>map(<?=json_encode($completions)?>)[d]||0),borderColor:'#0f8b8d'}]},options:{maintainAspectRatio:false}});new Chart(passChart,{type:'doughnut',data:{labels:['Fail','Pass'],datasets:[{data:[<?=json_encode(array_column($pf,'n'),JSON_NUMERIC_CHECK)?>].flat(),backgroundColor:['#d9534f','#0f8b8d']}]},options:{maintainAspectRatio:false}});new Chart(careersChart,{type:'bar',data:{labels:<?=json_encode(array_column($explored,'title'))?>,datasets:[{label:'Progress records',data:<?=json_encode(array_column($explored,'n'),JSON_NUMERIC_CHECK)?>,backgroundColor:'#173b67'}]},options:{maintainAspectRatio:false,indexAxis:'y'}});new Chart(riaChart,{type:'radar',data:{labels:<?=json_encode(array_map('ucfirst',array_column($riasec,'interest_type')))?>,datasets:[{label:'Average score',data:<?=json_encode(array_column($riasec,'n'),JSON_NUMERIC_CHECK)?>,borderColor:'#0f8b8d',backgroundColor:'rgba(15,139,141,.15)'}]},options:{maintainAspectRatio:false,scales:{r:{min:0,max:100}}}})});</script><?php require __DIR__.'/includes/footer.php';?>
